45: // If agy or git is unavailable, the fix records checkpoint: null with the
46: // reason — honest, never faked.
47: function entireCheckpoint(label, incidentId) {
48:   try {
49:     // 1. Real agent session: agy writes the repair plan file (its own reasoning, recorded)
50:     const planFile = join(ROOT, 'fixes', `${incidentId}-repair-plan.md`);
51:     const prompt = `Create the file ${planFile} with a one-line heading 'Repair plan for ${incidentId}: ${label}' and nothing else. Make only that change.`;
52:     execFileSync('agy', ['-p', prompt], {
53:       cwd: ROOT, timeout: 120000, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'],
54:     });
55:     // 2. Commit it: the checkpoint anchor is born (session + commit)
56:     execFileSync('git', ['add', planFile], { cwd: ROOT, encoding: 'utf8' });
57:     execFileSync('git', ['commit', '-m', `Entire pre-fix anchor: ${label} (${incidentId})`], { cwd: ROOT, encoding: 'utf8' });
58:     // 3. Read the checkpoint this just created
59:     const out = execFileSync('entire', ['checkpoint', 'list'], {
60:       cwd: ROOT, timeout: 30000, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'],
61:       env: { ...process.env, ENTIRE_TOKEN_STORE: 'file', PATH: process.env.PATH },
62:     });
63:     const m = out.match(/●\s+([0-9A-Z]{20,})/);
64:     return { ok: true, id: m ? m[1] : null, raw: out.slice(0, 300) };
65:   } catch (e) {
66:     return { ok: false, reason: String(e.message || e).slice(0, 200) };
67:   }
68: }
